I'll analyze EVAL-02's GraphQL API for security threats using STRIDE.

```json
{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-02",
  "sketch": {
    "components": ["GraphQL API endpoint", "Product catalog", "Review system", "Customer profile store", "Storefront client"],
    "dataStores": ["Customer profiles", "Product database", "Reviews"],
    "externalServices": [],
    "trustBoundaries": ["Public internet to GraphQL API"],
    "dataClasses": ["pii"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Unauthenticated access to customer profiles",
      "scenario": "An attacker directly queries the public GraphQL endpoint to access customer profiles without authentication. They can enumerate all customers by requesting profile data through the nested query interface, exposing PII of all users.",
      "component": "GraphQL API endpoint",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        {
          "quote": "Clients can request nested queries of products, reviews and customer profiles"
        },
        {
          "quote": "The storefront uses a public GraphQL endpoint"
        }
      ],
      "asvs": ["V4.1.1", "V8.3.4"],
      "cwe": ["CWE-306"],
      "plainLanguage": "Anyone can read all customer data because there's no login required to access the API",
      "requirement": {
        "title": "Require authentication for customer profile access",
        "given": "a client requests customer profile data",
        "when": "the query reaches the GraphQL resolver",
        "then": "reject the request unless a valid authenticated session token is present"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Resource exhaustion via deeply nested queries",
      "scenario": "An attacker crafts GraphQL queries with excessive nesting depth (e.g., product -> reviews -> customer -> reviews -> customer repeated 20+ times). Without query complexity limits, each request consumes exponentially more database queries and memory, eventually exhausting server resources and crashing the API.",
      "component": "GraphQL API endpoint",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        {
          "quote": "Clients can request nested queries of products, reviews and customer profiles"
        }
      ],
      "asvs": ["V13.4.1", "V11.1.1"],
      "cwe": ["CWE-400"],
      "plainLanguage": "Someone can crash the site by sending a complicated query that makes the server do too much work",
      "requirement": {
        "title": "Enforce query depth and complexity limits",
        "given": "a GraphQL query is received",
        "when": "the query parser analyzes it",
        "then": "reject queries exceeding depth 7 or complexity score 1000, and return error code QUERY_TOO_COMPLEX"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Schema disclosure via introspection in production",
      "scenario": "An attacker uses GraphQL introspection to download the complete API schema, learning all available queries, mutations, types, and fields including internal ones not meant for public access. This reveals implementation details, sensitive field names, and admin-only operations, making it easier to find other vulnerabilities.",
      "component": "GraphQL API endpoint",
      "likelihood": 5,
      "impact": 2,
      "evidence": [
        {
          "quote": "Introspection is enabled in production"
        }
      ],
      "asvs": ["V13.4.3"],
      "cwe": ["CWE-200"],
      "plainLanguage": "Attackers can download a complete map of the API showing all hidden features and data fields",
      "requirement": {
        "title": "Disable introspection in production",
        "given": "a GraphQL introspection query is received",
        "when": "the environment is production",
        "then": "return error INTROSPECTION_DISABLED instead of schema details"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Mass customer data harvesting without rate limiting",
      "scenario": "An attacker writes a script that enumerates customer IDs (or uses introspection to find enumeration queries) and batches hundreds of profile requests per second. Without rate limiting on the public endpoint, they harvest the complete customer database in minutes, stealing PII for resale or identity theft.",
      "component": "GraphQL API endpoint",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "The storefront uses a public GraphQL endpoint"
        },
        {
          "quote": "customer profiles"
        }
      ],
      "asvs": ["V4.2.2"],
      "cwe": ["CWE-799"],
      "plainLanguage": "Someone can download every customer's personal information by running an automated script",
      "requirement": {
        "title": "Rate limit GraphQL queries by IP and query cost",
        "given": "requests from a client IP exceed 100 query cost units per minute",
        "when": "the rate limiter evaluates the request",
        "then": "return HTTP 429 with Retry-After header for 60 seconds"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Field-level authorization bypass on sensitive profile fields",
      "scenario": "Customer profiles contain fields like email, phone, address, payment methods. An attacker crafts queries requesting sensitive fields that should be restricted to the profile owner. If GraphQL resolvers lack field-level authorization, the API returns all requested fields to any caller, exposing sensitive PII even if basic profile viewing is public.",
      "component": "Customer profile store",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "customer profiles"
        }
      ],
      "asvs": ["V4.1.3"],
      "cwe": ["CWE-639"],
      "plainLanguage": "Even if public profiles exist, private details like email and phone leak because the API doesn't check permissions field-by-field",
      "requirement": {
        "title": "Implement field-level authorization for sensitive customer data",
        "given": "a query requests fields marked sensitive (email, phone, address, payment)",
        "when": "the resolver fetches customer data",
        "then": "return null for those fields unless the authenticated user owns the profile or has admin role"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Query batching abuse for resource exhaustion",
      "scenario": "GraphQL supports sending multiple operations in one HTTP request. An attacker sends batches of 100+ expensive queries (each requesting deeply nested data) in a single POST. The server processes all queries before responding, multiplying resource consumption and enabling one client to monopolize server capacity, starving legitimate users.",
      "component": "GraphQL API endpoint",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "public GraphQL endpoint"
        }
      ],
      "asvs": ["V13.4.1"],
      "cwe": ["CWE-400"],
      "plainLanguage": "Someone can send many queries at once in a single request, overwhelming the server",
      "requirement": {
        "title": "Limit batched operations per request",
        "given": "a GraphQL request contains multiple operations",
        "when": "the batch size is validated",
        "then": "reject requests with more than 10 operations, returning error MAX_BATCH_SIZE_EXCEEDED"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Circular reference queries causing infinite loops",
      "scenario": "If the schema allows circular references (customer -> reviews -> customer or product -> relatedProducts -> product), an attacker crafts queries exploiting these cycles without depth limits. The resolver enters infinite loops or exponential fan-out, consuming memory until the process crashes or times out.",
      "component": "GraphQL API endpoint",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "nested queries of products, reviews and customer profiles"
        }
      ],
      "asvs": ["V13.4.1"],
      "cwe": ["CWE-674"],
      "plainLanguage": "Queries that loop back on themselves (like asking for a customer's reviews, then those customers, then their reviews again) can crash the server",
      "requirement": {
        "title": "Detect and prevent circular query paths",
        "given": "a query contains circular references",
        "when": "the query validator analyzes the selection set",
        "then": "reject with error CIRCULAR_QUERY_DETECTED if the same type appears more than 3 times in a path"
      }
    }
  ]
}
```

